cipher = """"""

h = ""

for x in cipher.replace("DW", " ").split():
    x = x.replace("S", "").replace("D", "").replace("Z", "")
    h += format(int("".join("1" if c == "O" else "0" for c in x), 2), "02x")

for _ in range(2):
    h = "".join(chr(int(h[i:i+2], 16)) for i in range(0, len(h), 2))

print(h)